// Embed canvas-script-api.source.js as a string module, so bundlers ship it and nothing reads files at run time.
import { readFileSync, writeFileSync } from 'node:fs'
const source = readFileSync(new URL('../src/canvas-script-api.source.js', import.meta.url), 'utf8')
new Function(`return ${source.replace(/^\/\/.*\n/gm, '')}`) // syntax check
writeFileSync(new URL('../src/canvas-script-api.ts', import.meta.url),
  '// Generated by scripts/embed-canvas-script.mjs from canvas-script-api.source.js. Edit that file, then run the script.\n' +
  `export const CANVAS_SCRIPT_API_SOURCE: string = ${JSON.stringify(source.replace(/^\/\/.*\n/gm, '').trim())}\n`)
